/** Only run on client */
import { createSubscriber } from "svelte/reactivity";
import type { FuncSchemas } from "./schemas.js";

/** Read a text/event-stream response and yield the payload of each `data:` event, throwing on an `error` event. */
async function* readEventStream(response: Response): AsyncGenerator<unknown> {
	// If the response has no body: there is nothing to read.
	if (!response.body) return;
	const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
	let buffer = "";
	/** Parse a raw event into its type and payload, or null when it has no `data:` line. */
	const parseEvent = (event: string) => {
		let type = "message";
		const dataLines: string[] = [];
		for (const line of event.split("\n")) {
			if (line.startsWith("event: ")) type = line.slice(7);
			else if (line.startsWith("data: ")) dataLines.push(line.slice(6));
		}
		if (dataLines.length === 0) return null;
		const payload = dataLines.join("\n");
		// If the payload is valid JSON: use the parsed value with `{ $date }` tags turned back into dates, otherwise keep the raw text.
		try {
			const data: unknown = JSON.parse(payload, (_key, value) => (value && typeof value === "object" && typeof value.$date === "string" ? new Date(value.$date) : value));
			return { type, data };
		} catch {
			return { type, data: payload };
		}
	};
	try {
		while (true) {
			const { done, value } = await reader.read();
			// If the stream ended: flush any remaining event.
			const events = done ? [buffer] : (buffer + value).split("\n\n");
			buffer = done ? "" : (events.pop() ?? "");
			for (const event of events) {
				const parsed = parseEvent(event);
				if (parsed === null) continue;
				// If the server sent an error event: stop reading and throw its message.
				if (parsed.type === "error") throw new Error(String(parsed.data));
				yield parsed.data;
			}
			if (done) break;
		}
	} finally {
		// Close the connection if the caller stops early.
		await reader.cancel().catch(() => {});
	}
}

/** Use functions */
export async function useFunc<K extends keyof FuncSchemas>(functionName: K, apiLoad: FuncSchemas[K]["in"], skipSleepTime = true, signal?: AbortSignal): Promise<FuncSchemas[K]["out"]> {
	// check if it's a form post, if yes set headers to empty
	const isFormData = (apiLoad as any) instanceof FormData;
	const headers: { [key: string]: any } = isFormData ? {} : ({ "Content-Type": "application/json" } as any);
	const body = (isFormData ? apiLoad : JSON.stringify(apiLoad)) as string | FormData;
	// send request and catch any error
	try {
		const requestStartTime = Date.now();
		const request = await fetch("/api/functions", { method: "POST", headers: { ...headers, functionName }, body, signal });
		// check if response is a text/event-stream
		const contentType: "text/event-stream" | "application/json" = request.headers.get("content-type") as any;
		if (contentType === "text/event-stream") {
			const response = { error: false, data: readEventStream(request) as any };
			return response;
		}
		// if request finish under 500 milliseconds: wait one second for better UX
		if (!skipSleepTime) {
			const elapsedTime = Date.now() - requestStartTime;
			const minWaitTime = 300;
			if (elapsedTime < minWaitTime) await new Promise((resolve) => setTimeout(resolve, minWaitTime - elapsedTime));
		}
		// return json
		const response = (await request.json()) as any;
		return response;
	} catch (err: any) {
		// return error
		const response = { error: true as const, data: err.message as string };
		return response;
	}
}

/** Value yielded by a function whose `out` schema is an async generator */
type FuncStreamItem<K extends keyof FuncSchemas> = Extract<FuncSchemas[K]["out"], { error: false }>["data"] extends AsyncGenerator<infer T> ? T : never;
/** Names of functions whose `out` schema is an async generator */
type FuncStreamName = { [K in keyof FuncSchemas]: [FuncStreamItem<K>] extends [never] ? never : K }[keyof FuncSchemas];

/** Live function stream that connects while a template or effect reads it, like a SvelteKit `query.live` */
class FuncLive<K extends FuncStreamName> {
	#functionName: K;
	#apiLoad: FuncSchemas[K]["in"];
	#current: { error: true; data: string } | { error: false; data: FuncStreamItem<K> } | undefined = undefined;
	#connected = false;
	#controller: AbortController | null = null;
	#update = () => {};
	#subscribe: () => void;
	#eventListeners = new Set<(data: FuncStreamItem<K>) => void>();
	#errorListeners = new Set<(message: string) => void>();

	constructor(functionName: K, apiLoad: FuncSchemas[K]["in"]) {
		this.#functionName = functionName;
		this.#apiLoad = apiLoad;
		// Connect on the first read inside an effect, and abort when the last reader is destroyed
		this.#subscribe = createSubscriber((update) => {
			this.#update = update;
			this.#connect();
			return () => {
				this.#controller?.abort();
				this.#controller = null;
			};
		});
	}

	/** Latest response: `{ error: false, data }` for each yielded value, `{ error: true, data: message }` on failure, or undefined before the first one */
	get current() {
		this.#subscribe();
		return this.#current;
	}

	/** Whether the stream is open */
	get connected() {
		this.#subscribe();
		return this.#connected;
	}

	/** Close the current stream and open a new one */
	reconnect() {
		this.#connect();
	}

	/** Run a callback for every value the server sends, and return a function that removes it */
	onEvent(callback: (data: FuncStreamItem<K>) => void) {
		// Subscribe like the getters, so calling it inside an effect keeps the stream open even when nothing else reads it
		this.#subscribe();
		this.#eventListeners.add(callback);
		return () => {
			this.#eventListeners.delete(callback);
		};
	}

	/** Run a callback with the message when the call or the stream fails, and return a function that removes it */
	onError(callback: (message: string) => void) {
		// Subscribe like the getters, so calling it inside an effect keeps the stream open even when nothing else reads it
		this.#subscribe();
		this.#errorListeners.add(callback);
		return () => {
			this.#errorListeners.delete(callback);
		};
	}

	/** Close the current stream, keeping the last value until `reconnect` */
	disconnect() {
		this.#controller?.abort();
		this.#controller = null;
		this.#connected = false;
		this.#update();
	}

	/** Open the stream and store each value it yields */
	async #connect() {
		// Abort any open stream, so only one connection runs at a time
		this.#controller?.abort();
		const controller = new AbortController();
		this.#controller = controller;

		const response = await useFunc(this.#functionName, this.#apiLoad, true, controller.signal);
		// If aborted while connecting: a newer connection or the cleanup owns the state.
		if (controller.signal.aborted) return;
		// If the call failed: keep its error response.
		if (response.error) {
			this.#current = response;
			this.#update();
			for (const listener of this.#errorListeners) listener(response.data);
			return;
		}

		this.#connected = true;
		this.#update();
		try {
			// The generic `K` hides the narrowed type, so name the generator type `FuncStreamItem` gives
			for await (const value of response.data as AsyncGenerator<FuncStreamItem<K>>) {
				this.#current = { error: false, data: value };
				this.#update();
				// Run the event callbacks after `current` is set, so they can read it too
				for (const listener of this.#eventListeners) listener(value);
			}
		} catch (err) {
			// If the stream failed and was not aborted: store the error, since aborting throws too.
			if (!controller.signal.aborted) {
				const message = err instanceof Error ? err.message : String(err);
				this.#current = { error: true, data: message };
				for (const listener of this.#errorListeners) listener(message);
			}
		} finally {
			// If this is still the active connection: mark it closed.
			if (this.#controller === controller || this.#controller === null) {
				this.#connected = false;
				this.#update();
			}
		}
	}
}

/** Use a streamed function as live state: read `.current`, `.connected`, and call `.reconnect()` */
export function useFuncLive<K extends FuncStreamName>(functionName: K, apiLoad: FuncSchemas[K]["in"]) {
	return new FuncLive(functionName, apiLoad);
}

/** Only run on server to avoid loading zod to client */
import { z } from "zod";
import type { RequestEvent } from "@sveltejs/kit";

/** Function schemas */
export const functionsSchemas = {
	toggleDarkMode: {
		in: z.object().nullish(),
		out: z.object({ isDarkMode: z.boolean() }),
		isPublic: true,
	},
	userCreate: {
		in: z.object({ email: z.email() }),
		out: z.string(),
		isPublic: true,
	},
	userDelete: {
		in: z.object({ email: z.email() }),
		out: z.string(),
		isPublic: true,
	},
	userDeletePrivate: {
		in: z.object({ email: z.email() }),
		out: z.string(),
		isPublic: false,
	},
	fileUpload: {
		in: z.custom<FormData>((value) => value instanceof FormData),
		out: z.object({ name: z.string(), size: z.number(), type: z.string() }),
		isPublic: true,
	},
	textStream: {
		in: z.object({ prompt: z.string().min(1) }),
		out: z.custom<AsyncGenerator<string>>(() => true),
		isPublic: true,
	},
	liveTicker: {
		in: z.object({ throwError: z.boolean().optional() }),
		out: z.custom<AsyncGenerator<{ count: number; price: number; time: Date }>>(() => true),
		isPublic: true,
	},
};

/** Function schemas type */
export type FuncSchemas = {
	[K in keyof typeof functionsSchemas]: {
		in: z.infer<(typeof functionsSchemas)[K]["in"]>;
		out: { error: true; data: string } | { error: false; data: z.infer<(typeof functionsSchemas)[K]["out"]> };
		isPublic?: boolean;
	};
};

/** Function response type */
export type FuncResponse<K extends keyof FuncSchemas> = { error: true; data: string } | { error: false; data: z.infer<(typeof functionsSchemas)[K]["out"]> };

/** Type helper to create function response */
export type FuncHandler<K extends keyof FuncSchemas> = (props: {
	event: Omit<RequestEvent, "request"> & {
		request: Omit<RequestEvent["request"], "json"> & {
			json: () => Promise<FuncSchemas[K]["in"]>;
		};
	};
	inputData: FuncSchemas[K]["in"];
}) => FuncSchemas[K]["out"] | Promise<FuncSchemas[K]["out"]> | Promise<Response> | Response;

/** Function response data type */
export type FunctionHookErrorResData = { error: true; data: string };

/** Only run on server */
import { z } from "zod";
import { functionsSchemas } from "./schemas.js";
import type { RequestHandler } from "@sveltejs/kit";
import type { FuncSchemas, FunctionHookErrorResData } from "./schemas.js";

const moduleFiles = import.meta.glob("#lib/functions/handlers/*.ts", { eager: true });
const handlers: Record<keyof FuncSchemas, Function> = {} as Record<keyof FuncSchemas, Function>;
const functions: (keyof FuncSchemas)[] = [];
// Loop all functions exported by file
for (const handlerModule of Object.values(moduleFiles)) {
	// handlerModule is an object with multiple exported functions
	if (handlerModule && typeof handlerModule === "object") {
		// Get all exported functions from this module
		for (const [exportName, exportedFunction] of Object.entries(handlerModule)) {
			// Only add if it's actually a function
			if (typeof exportedFunction === "function") {
				handlers[exportName as keyof FuncSchemas] = exportedFunction;
				functions.push(exportName as keyof FuncSchemas);
			}
		}
	}
}

/** Convert zod error to string */
const convertZodErrorToString = (functionName: keyof FuncSchemas, error: z.ZodError) => {
	const errors: { message: string; path: string[] }[] = JSON.parse(error.message);
	return errors.map((err) => `${err.message} from function '${functionName}' field '${err.path[0]}'`).join("\n");
};

/** Handle all request to this POST server endpoint */
const POST: RequestHandler = async (event) => {
	const functionName = event.request.headers.get("functionName") as null | keyof FuncSchemas;

	// Check if functionName header was provided
	if (!functionName) {
		const response = { error: true as const, data: "header 'functionName' it's required" as string };
		return Response.json(response);
	}

	// Check if function exists was exported from folder handlers
	if (!(functionName in handlers)) {
		const error: FunctionHookErrorResData = { error: true, data: `Function '${functionName}' does not exists` };
		return Response.json(error);
	}

	// Check if current request to function is permitted (if not public and no user data)
	if (!functionsSchemas[functionName].isPublic && !event.locals.userData) {
		const error: FunctionHookErrorResData = { error: true, data: `Function '${functionName}' is not a public function. If public, set it inside schema using isPublic:true.` };
		return Response.json(error);
	}

	// Validate input data (we do it on the server side to avoid importing zod to the client)
	const isFormData = (functionsSchemas[functionName].in.def.type as string) === "custom";
	const request = event.request.clone();
	const inputData = await request[isFormData ? "formData" : "json"]();
	const parseRes = functionsSchemas[functionName].in.safeParse(inputData);
	// If not validated, return error
	if (!parseRes.success) {
		const error = convertZodErrorToString(functionName, parseRes.error);
		const response = { error: true, data: error };
		return Response.json(response);
	}

	// Handle function
	const handlerResponse = handlers[functionName]({ event, inputData });
	const outputData: FuncSchemas[typeof functionName]["out"] = !(handlerResponse instanceof Promise) ? handlerResponse : await handlerResponse;

	// If returning raw response: return it as it's
	if (outputData instanceof Response) return outputData;
	const headers = new Headers({ "content-type": "application/json" });

	// If returning an async generator: stream each yielded value as a server-sent event, skipping output validation since streamed schemas are `z.custom`
	if (!outputData.error && outputData.data && typeof outputData.data === "object" && Symbol.asyncIterator in outputData.data) {
		const generator = outputData.data as AsyncGenerator<unknown>;
		const stream = new ReadableStream<string>({
			// Runs each time the client is ready for the next event
			async pull(controller) {
				try {
					const { done, value } = await generator.next();
					// If the generator finished: end the stream
					if (done) return controller.close();
					// Tag dates as `{ $date }`, since `toJSON` turns them into strings before the replacer sees them
					const payload = JSON.stringify(value, function (this: Record<string, unknown>, key: string, val: unknown) {
						return this[key] instanceof Date ? { $date: this[key].toISOString() } : val;
					});
					controller.enqueue(`data: ${payload}\n\n`);
				} catch (err) {
					// If the generator threw: send the message as an error event and end the stream
					const message = err instanceof Error ? err.message : String(err);
					controller.enqueue(`event: error\ndata: ${JSON.stringify(message)}\n\n`);
					controller.close();
				}
			},
			// Stop the generator when the client disconnects, which runs its `finally` block on its next yield
			async cancel() {
				await generator.return(undefined);
			},
		});
		return new Response(stream.pipeThrough(new TextEncoderStream()), { headers: { "content-type": "text/event-stream", "cache-control": "no-cache" } });
	}

	// if not returning error: validate output
	if (!outputData.error) {
		const parseRes = functionsSchemas[functionName]["out"].safeParse(outputData.data);
		// if output was not validated: return error
		if (!parseRes.success) {
			const error = convertZodErrorToString(functionName, parseRes.error);
			return new Response(JSON.stringify({ error: true, data: error }), { headers });
		}
	}

	const response = new Response(JSON.stringify(outputData), { headers });
	return response;
};

export { POST, functions };

import { dev } from "$app/env";
import type { FuncHandler } from "#lib/functions/schemas.js";

/** Toggle theme */
export const toggleDarkMode: FuncHandler<"toggleDarkMode"> = async ({ event }) => {
	const isDarkMode = event.cookies.get("theme") === "dark";
	const theme = isDarkMode ? "light" : "dark";
	// Save the theme for a week; only send it over https outside dev
	event.cookies.set("theme", theme, { path: "/", httpOnly: true, sameSite: "lax", secure: !dev, maxAge: 60 * 60 * 24 * 7 });
	return { error: false, data: { isDarkMode: !isDarkMode } };
};

import type { FuncHandler } from "#lib/functions/schemas.js";

/** Create user */
export const userCreate: FuncHandler<"userCreate"> = async ({ event, inputData }) => {
	const email = inputData.email;
	// This is pointless since input data gets checked before getting here
	if (!email) return { error: true, data: "Please provide user's email." };
	// Create user and return message
	return { error: false, data: `User with email ${email} created.` };
};

/** Delete user */
export const userDelete: FuncHandler<"userDelete"> = async ({ event, inputData }) => {
	const email = inputData.email;
	// This is pointless since input data gets checked before getting here
	if (!email) return { error: true, data: "Please provide user's email." };
	// Create user and return message
	return { error: false, data: `User with email ${email} deleted.` };
};

/** Delete user */
export const userDeletePrivate: FuncHandler<"userDeletePrivate"> = async ({ event, inputData }) => {
	const email = inputData.email;
	// This is pointless since input data gets checked before getting here
	if (!email) return { error: true, data: "Please provide user's email." };
	// Create user and return message
	return { error: false, data: `User with email ${email} deleted.` };
};

/** Read an uploaded file from form data */
export const fileUpload: FuncHandler<"fileUpload"> = async ({ inputData }) => {
	const file = inputData.get("file");
	// If no file was sent: return an error.
	if (!(file instanceof File) || !file.size) return { error: true, data: "Please choose a file to upload." };
	// Return the file details without saving the file
	return { error: false, data: { name: file.name, size: file.size, type: file.type || "unknown" } };
};

/** Stream a reply one word at a time */
export const textStream: FuncHandler<"textStream"> = async ({ inputData }) => {
	const words = `You said "${inputData.prompt}". This reply is streamed from the server one word at a time.`.split(" ");
	const encoder = new TextEncoder();
	const stream = new ReadableStream({
		async start(controller) {
			// Send each word as a server-sent event, then close the stream
			for (const word of words) {
				controller.enqueue(encoder.encode(`data: ${JSON.stringify(`${word} `)}\n\n`));
				await new Promise((resolve) => setTimeout(resolve, 80));
			}
			controller.close();
		},
	});
	return new Response(stream, { headers: { "content-type": "text/event-stream" } });
};

/** Stream a random price every second, like a live ticker */
export const liveTicker: FuncHandler<"liveTicker"> = async ({ event, inputData }) => {
	/** Yield a new price each second, ending after a minute so idle docs tabs do not keep a stream open */
	async function* ticker() {
		let price = 100;
		for (let count = 1; count <= 60; count++) {
			// If testing errors: throw on the third event, so the client gets an error mid-stream
			if (inputData.throwError && count === 3) throw new Error("Ticker failed on purpose.");
			price = Math.round((price + (Math.random() - 0.5) * 2) * 100) / 100;
			yield { count, price, time: new Date() };
			// Wait a second, or stop right away when the client disconnects
			await new Promise((resolve) => {
				const timeout = setTimeout(resolve, 1000);
				event.request.signal.addEventListener("abort", () => {
					clearTimeout(timeout);
					resolve(null);
				}, { once: true });
			});
			// If the client disconnected: end the generator
			if (event.request.signal.aborted) return;
		}
	}
	return { error: false, data: ticker() };
};
